fn solve(a: i8) -> i8 {
    // We assume 0 <= a <= 127, so casting to u8 is safe and
    // allows us to use unsigned division and remainder.
    let mut v = a as u8;
    let mut count: i8 = 0;

    // Repeatedly peel off the least significant octal digit
    // and check if it equals 1.
    while v != 0 {
        if v % 8 == 1 {
            count += 1;
        }
        v /= 8;
    }

    count
}

